contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dep, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(minSum == 0);
        require(dep > 0);
        require(address(this).balance >= dep);

        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;

        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint balAfterDepC = address(c).balance;
        uint balAfterDepThis = address(this).balance;

        bool reverted;
        c.Collect(dep); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted && address(this).balance == balBeforeThis && balAfterDepC == balBeforeC + dep);
    }

    receive() external payable {}
}

