pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 dep, uint256 minSum) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        minSum = 0;
        vm.assume(dep > 0);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;
        try c.Deposit{value: dep}() {} catch { return; }
        uint balAfterDepC = address(c).balance;
        uint balAfterDepThis = address(this).balance;
        bool reverted;
        try c.Collect(dep) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(this).balance == balBeforeThis && balAfterDepC == balBeforeC + dep);
    }

    function testFuzz_run(uint256 dep, uint256 minSum) public {
        _run(dep, minSum);
    }

    receive() external payable {}
}
